#include <iostream>
#include <iomanip>
#include <array>
#include <cstddef>

int main() {
    // 1. Initializer list with exact size
    std::array<int, 5> listArray = {32, 27, 64, 18, 95};

    // 2. Partial initialization (remaining elements become 0)
    std::array<int, 5> partialArray = {10, 20};

    // 3. Manual zero re-initialization via loop
    std::array<int, 5> loopArray;
    for (std::size_t i = 0; i < loopArray.size(); ++i) {
        loopArray[i] = 0;
    }

    std::cout << "Element" << std::setw(13) << "Value" << std::endl;
    for (std::size_t j = 0; j < listArray.size(); ++j) {
        std::cout << std::setw(7) << j << std::setw(13) << listArray[j] << std::endl;
    }

    std::cout << "\nPartial array element 4: " << partialArray[4] << std::endl;
    std::cout << "Loop array element 0: " << loopArray[0] << std::endl;

    return 0;
}

#include <iostream>
#include <iomanip>
#include <array>
#include <cstddef>

int main() {
    // Named constant eliminates magic numbers
    const std::size_t arraySize = 5;
    std::array<int, arraySize> s;

    // Populate array elements with calculations: 2, 4, 6, 8, 10
    for (std::size_t i = 0; i < s.size(); ++i) {
        s[i] = 2 + 2 * i;
    }

    std::cout << "Element" << std::setw(13) << "Value" << std::endl;
    for (std::size_t j = 0; j < s.size(); ++j) {
        std::cout << std::setw(7) << j << std::setw(13) << s[j] << std::endl;
    }

    return 0;
}
